import { serve } from "https://deno.land/std@0.190.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.50.0";
import {
  calculateDueExecutions,
  calculateNextExecution,
  getMadridDateKey,
} from '../_shared/recurringSchedule.ts';
import {
  assertAdminManagerOrServiceRole,
  authorizationErrorResponse,
} from '../_shared/edgeAuthorization.ts';

const MAX_OCCURRENCES_PER_TASK = 31;

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

const handler = async (req: Request): Promise<Response> => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const recurringCronSecret = Deno.env.get('RECURRING_TASKS_CRON_SECRET') ?? '';
    
    const supabase = createClient(supabaseUrl, supabaseServiceKey);
    await assertAdminManagerOrServiceRole(req, supabase, supabaseServiceKey, {
      dedicatedSecret: {
        headerName: 'X-Cron-Secret',
        value: recurringCronSecret,
        actorKind: 'cron',
      },
    });
    
    console.log("🔄 Starting recurring tasks processing...");
    
    const today = getMadridDateKey();
    
    // Get all active recurring tasks that are due for execution (using snake_case DB columns)
    const { data: recurringTasks, error: fetchError } = await supabase
      .from('recurring_tasks')
      .select('*, properties:propiedad_id(nombre, direccion)')
      .eq('is_active', true)
      .lte('next_execution', today);

    if (fetchError) {
      console.error("❌ Error fetching recurring tasks:", fetchError);
      throw fetchError;
    }

    console.log(`📋 Found ${recurringTasks?.length || 0} tasks to process`);

    if (!recurringTasks || recurringTasks.length === 0) {
      return new Response(JSON.stringify({ 
        message: "No recurring tasks to process",
        processed: 0,
        generatedTasks: [],
        updatedRecurringTasks: 0
      }), {
        status: 200,
        headers: { "Content-Type": "application/json", ...corsHeaders },
      });
    }

    const generatedTasks: any[] = [];
    const updatedTasks = new Set<string>();
    const failures: Array<{ recurringTaskId: string; executionDate: string; error: string }> = [];
    let hasBacklog = false;

    for (const rt of recurringTasks) {
      try {
        console.log(`🔨 Processing task: ${rt.name}`);

        const propertyName = rt.properties?.nombre || rt.name;
        const propertyAddress = rt.properties?.direccion || '';
        const scheduleSnapshot = {
          frequency: rt.frequency,
          interval_days: rt.interval_days,
          days_of_week: rt.days_of_week,
          day_of_month: rt.day_of_month,
          start_date: rt.start_date,
          end_date: rt.end_date,
        };
        const dueExecutions = calculateDueExecutions(
          rt,
          rt.next_execution,
          today,
          MAX_OCCURRENCES_PER_TASK,
        );
        hasBacklog ||= dueExecutions.hasMore;

        for (const executionDate of dueExecutions.dates) {
          const nextExecution = calculateNextExecution(rt, executionDate);
          const { data: materialization, error: materializationError } = await supabase
            .rpc('materialize_recurring_task', {
              p_recurring_task_id: rt.id,
              p_execution_date: executionDate,
              p_next_execution: nextExecution,
              p_schedule_snapshot: scheduleSnapshot,
            })
            .single();

          if (materializationError || !materialization) {
            const message = materializationError?.message
              || `La materialización de ${rt.name} no devolvió resultado`;
            failures.push({ recurringTaskId: rt.id, executionDate, error: message });
            hasBacklog = true;
            console.error(`❌ Error materializing recurring task ${rt.name}:`, message);

            const { error: executionLogError } = await supabase
              .from('recurring_task_executions')
              .insert({
                recurring_task_id: rt.id,
                execution_date: executionDate,
                success: false,
                error_message: message,
              });
            if (executionLogError) {
              console.error(`⚠️ Could not log recurring task failure ${rt.name}:`, executionLogError);
            }
            break;
          }

          updatedTasks.add(rt.id);
          if (materialization.was_created) {
            generatedTasks.push({
              id: materialization.generated_task_id,
              name: propertyName,
              executionDate,
            });
            console.log(`✅ Task ${rt.name} materialized atomically for ${executionDate}`);
          } else {
            console.log(`↩️ Task ${rt.name} for ${executionDate} already existed; state repaired`);
          }

          if (materialization.was_created && rt.cleaner_id) {
            try {
              const { data: cleanerData } = await supabase
                .from('cleaners')
                .select('name, email')
                .eq('id', rt.cleaner_id)
                .single();

              if (cleanerData?.email) {
                const emailRes = await fetch(
                  `${supabaseUrl}/functions/v1/send-recurring-task-email`,
                  {
                    method: 'POST',
                    headers: {
                      'Content-Type': 'application/json',
                      'Authorization': `Bearer ${supabaseServiceKey}`,
                    },
                    body: JSON.stringify({
                      cleanerEmail: cleanerData.email,
                      cleanerName: cleanerData.name || 'Trabajador',
                      taskData: {
                        property: propertyName,
                        address: propertyAddress,
                        date: executionDate,
                        startTime: rt.start_time,
                        endTime: rt.end_time,
                        type: rt.type,
                        recurringTaskName: rt.name,
                      },
                    }),
                  },
                );

                if (!emailRes.ok) {
                  const errText = await emailRes.text();
                  console.error(`⚠️ Email send failed for ${cleanerData.email}:`, errText);
                }
              }
            } catch (emailError: any) {
              console.error(`⚠️ Error sending email for task ${rt.name}:`, emailError.message);
            }
          }

          if (nextExecution === null) {
            console.log(`🔚 Task ${rt.name} deactivated - reached end date`);
          }
        }
      } catch (taskError: any) {
        failures.push({
          recurringTaskId: rt.id,
          executionDate: rt.next_execution,
          error: taskError.message || String(taskError),
        });
        hasBacklog = true;
        console.error(`❌ Error processing task ${rt.name}:`, taskError);
      }
    }

    console.log(
      `✨ Processing complete. Generated ${generatedTasks.length} tasks, `
      + `updated ${updatedTasks.size} recurring tasks, failures ${failures.length}`,
    );

    return new Response(JSON.stringify({
      message: failures.length > 0
        ? "Recurring tasks processed with errors"
        : "Recurring tasks processed successfully",
      processed: generatedTasks.length,
      generatedTasks,
      updatedRecurringTasks: updatedTasks.size,
      failed: failures.length,
      errors: failures,
      hasBacklog,
    }), {
      status: 200,
      headers: { "Content-Type": "application/json", ...corsHeaders },
    });

  } catch (error: any) {
    const authResponse = authorizationErrorResponse(error, corsHeaders);
    if (authResponse) return authResponse;
    console.error("❌ Error in process-recurring-tasks function:", error);
    return new Response(JSON.stringify({ 
      error: error.message,
      details: "Failed to process recurring tasks"
    }), {
      status: 500,
      headers: { "Content-Type": "application/json", ...corsHeaders },
    });
  }
};

serve(handler);

export interface RecurringSchedule {
  frequency: 'daily' | 'weekly' | 'monthly' | string;
  interval_days?: number | null;
  days_of_week?: number[] | null;
  day_of_month?: number | null;
  start_date: string;
  end_date?: string | null;
}

const DATE_KEY_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const DAY_MS = 24 * 60 * 60 * 1000;

function assertDateKey(value: string, fieldName: string): void {
  if (!DATE_KEY_PATTERN.test(value)) {
    throw new Error(`${fieldName} debe tener formato YYYY-MM-DD`);
  }
}

function parseDateKey(value: string): Date {
  assertDateKey(value, 'date');
  const [year, month, day] = value.split('-').map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));
  if (formatDateKey(date) !== value) {
    throw new Error(`Fecha civil inválida: ${value}`);
  }
  return date;
}

function formatDateKey(date: Date): string {
  return date.toISOString().slice(0, 10);
}

function addDays(dateKey: string, days: number): string {
  const date = parseDateKey(dateKey);
  date.setUTCDate(date.getUTCDate() + days);
  return formatDateKey(date);
}

function compareDateKeys(left: string, right: string): number {
  return left.localeCompare(right);
}

function laterDateKey(left: string, right: string): string {
  return compareDateKeys(left, right) >= 0 ? left : right;
}

function earlierDateKey(left: string, right: string): string {
  return compareDateKeys(left, right) <= 0 ? left : right;
}

function normalizedInterval(schedule: RecurringSchedule): number {
  return Math.max(1, Math.trunc(Number(schedule.interval_days) || 1));
}

function normalizedWeekdays(schedule: RecurringSchedule): number[] {
  const supplied = Array.from(new Set(schedule.days_of_week || []))
    .filter((day) => Number.isInteger(day) && day >= 0 && day <= 6)
    .sort((left, right) => left - right);
  if (supplied.length > 0) return supplied;
  return [parseDateKey(schedule.start_date).getUTCDay()];
}

function daysBetween(from: string, to: string): number {
  return Math.round((parseDateKey(to).getTime() - parseDateKey(from).getTime()) / DAY_MS);
}

function monthsBetween(from: Date, to: Date): number {
  return (to.getUTCFullYear() - from.getUTCFullYear()) * 12
    + (to.getUTCMonth() - from.getUTCMonth());
}

function lastDayOfMonth(year: number, monthIndex: number): number {
  return new Date(Date.UTC(year, monthIndex + 1, 0)).getUTCDate();
}

export function isRecurringOccurrence(schedule: RecurringSchedule, dateKey: string): boolean {
  assertDateKey(schedule.start_date, 'start_date');
  assertDateKey(dateKey, 'date');
  if (compareDateKeys(dateKey, schedule.start_date) < 0) return false;
  if (schedule.end_date && compareDateKeys(dateKey, schedule.end_date) > 0) return false;

  const interval = normalizedInterval(schedule);
  const start = parseDateKey(schedule.start_date);
  const candidate = parseDateKey(dateKey);

  switch (schedule.frequency) {
    case 'daily':
      return daysBetween(schedule.start_date, dateKey) % interval === 0;

    case 'weekly': {
      const startWeekDayMondayFirst = (start.getUTCDay() + 6) % 7;
      const candidateWeekDayMondayFirst = (candidate.getUTCDay() + 6) % 7;
      const startWeek = addDays(schedule.start_date, -startWeekDayMondayFirst);
      const candidateWeek = addDays(dateKey, -candidateWeekDayMondayFirst);
      const weekDifference = daysBetween(startWeek, candidateWeek) / 7;
      return weekDifference >= 0
        && weekDifference % interval === 0
        && normalizedWeekdays(schedule).includes(candidate.getUTCDay());
    }

    case 'monthly': {
      const monthDifference = monthsBetween(start, candidate);
      if (monthDifference < 0 || monthDifference % interval !== 0) return false;
      const requestedDay = Math.max(
        1,
        Math.trunc(Number(schedule.day_of_month) || start.getUTCDate()),
      );
      const expectedDay = Math.min(
        requestedDay,
        lastDayOfMonth(candidate.getUTCFullYear(), candidate.getUTCMonth()),
      );
      return candidate.getUTCDate() === expectedDay;
    }

    default:
      throw new Error(`Frecuencia recurrente no soportada: ${schedule.frequency}`);
  }
}

function findFirstOccurrenceOnOrAfter(
  schedule: RecurringSchedule,
  minimumDate: string,
): string | null {
  let cursor = laterDateKey(schedule.start_date, minimumDate);
  const interval = normalizedInterval(schedule);
  const fallbackLimit = schedule.frequency === 'monthly'
    ? interval * 31 + 31
    : schedule.frequency === 'weekly'
      ? interval * 7 + 7
      : interval + 1;
  const hardEnd = schedule.end_date || addDays(cursor, fallbackLimit);

  while (compareDateKeys(cursor, hardEnd) <= 0) {
    if (isRecurringOccurrence(schedule, cursor)) return cursor;
    cursor = addDays(cursor, 1);
  }
  return null;
}

export function calculateInitialExecution(
  schedule: RecurringSchedule,
  todayMadrid: string,
): string | null {
  assertDateKey(todayMadrid, 'todayMadrid');
  return findFirstOccurrenceOnOrAfter(schedule, todayMadrid);
}

export function calculateNextExecution(
  schedule: RecurringSchedule,
  currentExecution: string,
): string | null {
  assertDateKey(currentExecution, 'currentExecution');
  return findFirstOccurrenceOnOrAfter(schedule, addDays(currentExecution, 1));
}

export function calculateOccurrences(
  schedule: RecurringSchedule,
  dateFrom: string,
  dateTo: string,
): string[] {
  assertDateKey(dateFrom, 'dateFrom');
  assertDateKey(dateTo, 'dateTo');
  if (compareDateKeys(dateFrom, dateTo) > 0) return [];

  let cursor = laterDateKey(schedule.start_date, dateFrom);
  const hardEnd = schedule.end_date
    ? earlierDateKey(schedule.end_date, dateTo)
    : dateTo;
  const occurrences: string[] = [];

  while (compareDateKeys(cursor, hardEnd) <= 0) {
    if (isRecurringOccurrence(schedule, cursor)) occurrences.push(cursor);
    cursor = addDays(cursor, 1);
  }
  return occurrences;
}

export function calculateDueExecutions(
  schedule: RecurringSchedule,
  firstExecution: string,
  todayMadrid: string,
  limit: number,
): { dates: string[]; hasMore: boolean } {
  assertDateKey(firstExecution, 'firstExecution');
  assertDateKey(todayMadrid, 'todayMadrid');
  if (!Number.isInteger(limit) || limit < 1) {
    throw new Error('limit must be a positive integer');
  }

  const dates: string[] = [];
  let execution: string | null = firstExecution;

  while (
    execution
    && compareDateKeys(execution, todayMadrid) <= 0
    && dates.length < limit
  ) {
    dates.push(execution);
    execution = calculateNextExecution(schedule, execution);
  }

  return {
    dates,
    hasMore: execution !== null && compareDateKeys(execution, todayMadrid) <= 0,
  };
}

export function getMadridDateKey(now: Date = new Date()): string {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Europe/Madrid',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(now);
  const values = Object.fromEntries(parts.map((part) => [part.type, part.value]));
  return `${values.year}-${values.month}-${values.day}`;
}

import type { SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2.50.0';

export type PrivilegedEdgeActor = {
  kind: 'service-role' | 'user' | 'cron';
  userId?: string;
  role?: string;
};

function extractBearer(req: Request): string | null {
  const header = req.headers.get('Authorization') || '';
  const match = header.match(/^Bearer\s+(.+)$/i);
  return match?.[1]?.trim() || null;
}

async function secretsMatch(provided: string | null, expected: string): Promise<boolean> {
  if (!provided || !expected) return false;
  const encoder = new TextEncoder();
  const [providedHash, expectedHash] = await Promise.all([
    crypto.subtle.digest('SHA-256', encoder.encode(provided)),
    crypto.subtle.digest('SHA-256', encoder.encode(expected)),
  ]);
  const providedBytes = new Uint8Array(providedHash);
  const expectedBytes = new Uint8Array(expectedHash);
  let difference = 0;
  for (let index = 0; index < providedBytes.length; index += 1) {
    difference |= providedBytes[index] ^ expectedBytes[index];
  }
  return difference === 0;
}

export async function assertAdminManagerOrServiceRole(
  req: Request,
  supabaseAdmin: SupabaseClient,
  serviceRoleKey: string,
  options?: {
    dedicatedSecret?: {
      headerName: string;
      value: string;
      actorKind: 'cron';
    };
  },
): Promise<PrivilegedEdgeActor> {
  const token = extractBearer(req);
  if (!token) {
    throw new Response('Missing authorization', { status: 401 });
  }

  if (serviceRoleKey && token === serviceRoleKey) {
    return { kind: 'service-role' };
  }

  const dedicatedSecret = options?.dedicatedSecret;
  if (
    dedicatedSecret
    && await secretsMatch(req.headers.get(dedicatedSecret.headerName), dedicatedSecret.value)
  ) {
    return { kind: dedicatedSecret.actorKind };
  }

  const { data: userData, error: userError } = await supabaseAdmin.auth.getUser(token);
  if (userError || !userData.user) {
    throw new Response('Invalid session', { status: 401 });
  }

  const { data: roles, error: roleError } = await supabaseAdmin
    .from('user_roles')
    .select('role')
    .eq('user_id', userData.user.id)
    .in('role', ['admin', 'manager'])
    .limit(1);

  if (roleError) {
    console.error('Unable to verify privileged Edge Function role:', roleError);
    throw new Response('Unable to verify authorization', { status: 500 });
  }

  const role = roles?.[0]?.role;
  if (!role) {
    throw new Response('Forbidden', { status: 403 });
  }

  return {
    kind: 'user',
    userId: userData.user.id,
    role,
  };
}

export function authorizationErrorResponse(error: unknown, corsHeaders: HeadersInit): Response | null {
  if (!(error instanceof Response)) return null;
  return new Response(error.body, {
    status: error.status,
    statusText: error.statusText,
    headers: { ...corsHeaders, 'Content-Type': 'text/plain; charset=utf-8' },
  });
}
